import atcoder/extra/monoid/monoid
import atcoder/extra/structure/compressed_dual_segtree_2d


proc addAction(
    a,
    b:
      int64
): int64 =
  a + b


proc zeroAction():
    int64 =
  0'i64


type
  AdditiveActionMonoid =
    CommutativeMonoidOf(
      int64,
      addAction,
      zeroAction,
    )

  AdditiveInt64Mapper =
    object


proc mapping(
    _:
      typedesc[
        AdditiveInt64Mapper
      ],
    action,
    value:
      int64
): int64 =
  value + action


proc xorAction(
    a,
    b:
      uint64
): uint64 =
  a xor b


proc zeroXor():
    uint64 =
  0'u64


type
  XorActionMonoid =
    CommutativeMonoidOf(
      uint64,
      xorAction,
      zeroXor,
    )

  XorMapper =
    object


proc mapping(
    _:
      typedesc[
        XorMapper
      ],
    action,
    value:
      uint64
): uint64 =
  value xor action


type
  Box =
    object
      value:
        int


  BoxMapper =
    object


proc mapping(
    _:
      typedesc[
        BoxMapper
      ],
    action:
      int64,
    value:
      Box
): Box =
  Box(
    value:
      value.value + int(
        action
      )
  )


