    116334'i64, 71015'i64,
  ]


var builder =
  initCompressedDualSegTree2DBuilder(
    int64,
    AdditiveActionMonoid,
    AdditiveInt64Mapper,
  )


for point in Points:
  builder.addPoint(
    point[0],
    point[1],
    point[2],
  )


var tree =
  builder.build()


doAssert tree.pointCount() ==
  PointCount


for point in Points:
  doAssert tree.containsPoint(
    point[0],
    point[1],
  )


for index in 0 ..< LogicalQueryCount:
  let event =
    Events[
      index
    ]

  tree.apply(
    event[0],
    event[1],
    event[2],
    event[3],
    event[4],
  )

  var actual:
    int64

  if (
    index and 1
  ) == 0:
    actual =
      tree.get(
        event[5],
        event[6],
      )
  else:
    actual =
      tree[
        event[5],
        event[6]
      ]

  doAssert actual ==
    ExpectedValues[
      index
    ]


block emptyTopology:
  var emptyBuilder =
    initCompressedDualSegTree2DBuilder(
      int64,
      AdditiveActionMonoid,
      AdditiveInt64Mapper,
    )

  var emptyTree =
    emptyBuilder.build()

  doAssert emptyTree.pointCount() ==
    0

  emptyTree.apply(
    -100,
    100,
    -200,
    200,
    17'i64,
  )


block duplicateRegistrationRejected:
  var duplicateBuilder =
    initCompressedDualSegTree2DBuilder(
      int64,
      AdditiveActionMonoid,
      AdditiveInt64Mapper,
    )

  duplicateBuilder.addPoint(
    3,
    4,
    10'i64,
  )

  duplicateBuilder.addPoint(
    3,
    4,
    20'i64,
  )

  var rejected =
    false

  try:
    discard duplicateBuilder.build()
  except ValueError:
    rejected =
      true

  doAssert rejected


block unregisteredGetRejected:
  var localBuilder =
    initCompressedDualSegTree2DBuilder(
      int64,
      AdditiveActionMonoid,
      AdditiveInt64Mapper,
    )

  localBuilder.addPoint(
    -10,
    20,
    5'i64,
  )

  let localTree =
    localBuilder.build()

  doAssert localTree.containsPoint(
    -10,
    20,
  )

  doAssert not localTree.containsPoint(
    -10,
    21,
  )

  var rejected =
    false

  try:
    discard localTree.get(
      -10,
      21,
    )
  except ValueError:
    rejected =
      true

  doAssert rejected


block arbitraryUnregisteredBoundaries:
  var localBuilder =
    initCompressedDualSegTree2DBuilder(
      int64,
      AdditiveActionMonoid,
      AdditiveInt64Mapper,
    )

  localBuilder.addPoint(
    -7,
    11,
    100'i64,
  )

  localBuilder.addPoint(
    19,
    -13,
    -4'i64,
  )

  var localTree =
    localBuilder.build()

  localTree.apply(
    -8,
    0,
    10,
    12,
    9'i64,
  )

  doAssert localTree[
    -7,
    11
  ] ==
    109'i64

  doAssert localTree[
    19,
    -13
  ] ==
    -4'i64


block xorAction:
  var xorBuilder =
    initCompressedDualSegTree2DBuilder(
      uint64,
      XorActionMonoid,
      XorMapper,
    )

  xorBuilder.addPoint(
    -2,
    5,
    1'u64,
  )

  xorBuilder.addPoint(
    10,
    -4,
    6'u64,
  )

  var xorTree =
    xorBuilder.build()

  xorTree.apply(
    -10,
    11,
    -10,
    10,
    7'u64,
  )

  xorTree.apply(
    -3,
    0,
    0,
    6,
    3'u64,
  )

  doAssert xorTree[
    -2,
    5
  ] ==
    (1'u64 xor 7'u64 xor 3'u64)

  doAssert xorTree[
    10,
    -4
  ] ==
    (6'u64 xor 7'u64)


block genericValue:
  var boxBuilder =
    initCompressedDualSegTree2DBuilder(
      Box,
      AdditiveActionMonoid,
      BoxMapper,
    )

  boxBuilder.addPoint(
    -5,
    -6,
    Box(
      value:
        10
    ),
  )

  boxBuilder.addPoint(
    8,
    9,
    Box(
      value:
        -3
    ),
  )

  var boxTree =
    boxBuilder.build()

  boxTree.apply(
    -100,
    0,
    -100,
    0,
    7'i64,
  )

  doAssert boxTree[
    -5,
    -6
  ].value ==
    17

  doAssert boxTree[
    8,
    9
  ].value ==
    -3


block mapperLaws:
  let value =
    Box(
      value:
        11
    )

  let
    a =
      7'i64

    b =
      -3'i64

  doAssert mapping(
    BoxMapper,
    AdditiveActionMonoid.e(),
    value,
  ).value ==
    value.value

  doAssert mapping(
    BoxMapper,
    AdditiveActionMonoid.op(
      a,
      b,
    ),
    value,
  ).value ==
    mapping(
      BoxMapper,
      a,
      mapping(
        BoxMapper,
        b,
        value,
      ),
    ).value


echo(
  "COMPRESSED_DUAL_SEGTREE_2D_CONTRACT_OK queries=" &
  $LogicalQueryCount &
  " oracle=" &
  OracleSha
)
